SELECT doc.retrieval_chunk_id AS chunk_id, chunk.modality, (MATCH(doc.word_search_text) AGAINST(#{query} IN NATURAL LANGUAGE MODE) + MATCH(doc.cjk_search_text) AGAINST(#{query} IN NATURAL LANGUAGE MODE) + 2 * EXISTS (SELECT 1 FROM retrieval_exact_term term WHERE term.retrieval_chunk_id = doc.retrieval_chunk_id AND term.owner_type = #{ownerType} AND term.owner_key = #{ownerKey} AND LOCATE(term.normalized_term, LOWER(#{query})) > 0)) AS score FROM retrieval_search_document doc JOIN retrieval_chunk chunk ON chunk.id = doc.retrieval_chunk_id WHERE doc.owner_type = #{ownerType} AND doc.owner_key = #{ownerKey} AND doc.status = 'ACTIVE' AND chunk.status = 'ACTIVE' AND chunk.citable = TRUE AND (
(doc.version_id = #{source.versionId} AND doc.revision_id = #{source.revisionId})
) AND ((#{includeText} = TRUE AND chunk.modality IN ('TEXT', 'TABLE')) OR (#{includeVisual} = TRUE AND chunk.modality = 'VISUAL')) AND (MATCH(doc.word_search_text) AGAINST(#{query} IN NATURAL LANGUAGE MODE) > 0 OR MATCH(doc.cjk_search_text) AGAINST(#{query} IN NATURAL LANGUAGE MODE) > 0 OR EXISTS (SELECT 1 FROM retrieval_exact_term term WHERE term.retrieval_chunk_id = doc.retrieval_chunk_id AND term.owner_type = #{ownerType} AND term.owner_key = #{ownerKey} AND LOCATE(term.normalized_term, LOWER(#{query})) > 0)) ORDER BY score DESC, doc.retrieval_chunk_id LIMIT #{limit}

SELECT chunk.id AS chunk_id, chunk.modality, chunk.quality_score AS score FROM retrieval_chunk chunk JOIN retrieval_chunk_evidence mapping ON mapping.retrieval_chunk_id = chunk.id AND mapping.role = 'PRIMARY' JOIN evidence_unit evidence ON evidence.id = mapping.evidence_id AND evidence.status = 'ACTIVE' JOIN material_version mv ON mv.id = evidence.version_id JOIN material material ON material.id = mv.material_id WHERE material.owner_type = #{ownerType} AND material.owner_key = #{ownerKey} AND material.lifecycle_state = 'ACTIVE' AND chunk.status = 'ACTIVE' AND chunk.citable = TRUE AND chunk.modality = 'VISUAL' AND (
(evidence.version_id = #{source.versionId} AND evidence.revision_id = #{source.revisionId})
) ORDER BY chunk.quality_score DESC, chunk.id LIMIT #{limit}

SELECT chunk.id AS chunk_id, chunk.modality, 1.0 AS score FROM retrieval_chunk_vector_projection projection JOIN retrieval_chunk chunk ON chunk.id = projection.retrieval_chunk_id JOIN retrieval_search_document doc ON doc.retrieval_chunk_id = chunk.id WHERE projection.vector_id IN #{id} AND projection.state = 'ACTIVE' AND chunk.status = 'ACTIVE' AND chunk.citable = TRUE AND doc.owner_type = #{ownerType} AND doc.owner_key = #{ownerKey} AND doc.status = 'ACTIVE' AND (
(doc.version_id = #{source.versionId} AND doc.revision_id = #{source.revisionId})
) ORDER BY FIELD(projection.vector_id, #{id})

SELECT chunk.id AS chunk_id, mapping.evidence_id, material.id AS material_id, mv.id AS version_id, mr.id AS revision_id, chunk.modality, page.page_no AS page_number, chunk.quality_score, chunk.retrieval_text_object_key, chunk.retrieval_text_object_version_id, chunk.retrieval_text_sha256, chunk.retrieval_text_byte_size, chunk.retrieval_text_content_type, visual.object_key AS visual_object_key, visual.object_version_id AS visual_object_version_id, visual.content_sha256 AS visual_content_sha256, visual.byte_size AS visual_byte_size, visual.content_type AS visual_content_type, material.display_name AS source_label FROM retrieval_chunk chunk JOIN retrieval_chunk_evidence mapping ON mapping.retrieval_chunk_id = chunk.id AND mapping.role = 'PRIMARY' JOIN evidence_unit evidence ON evidence.id = mapping.evidence_id AND evidence.status = 'ACTIVE' JOIN material_version mv ON mv.id = evidence.version_id JOIN material material ON material.id = mv.material_id JOIN material_processing_revision mr ON mr.id = evidence.revision_id AND mr.version_id = mv.id LEFT JOIN material_visual_artifact visual ON visual.revision_id = mr.id AND visual.object_key = evidence.visual_object_key AND visual.object_version_id = evidence.visual_object_version_id LEFT JOIN material_page page ON page.id = evidence.page_id AND page.revision_id = mr.id WHERE chunk.id IN #{id} AND material.owner_type = #{ownerType} AND material.owner_key = #{ownerKey} AND material.lifecycle_state = 'ACTIVE' AND (material.retention_class = 'RETAINED' OR material.expires_at > UTC_TIMESTAMP(3)) AND mr.state = 'READY' AND chunk.status = 'ACTIVE' AND chunk.citable = TRUE AND ((chunk.modality = 'VISUAL' AND visual.byte_size IS NOT NULL AND visual.content_type LIKE 'image/%') OR (chunk.modality <> 'VISUAL' AND chunk.retrieval_text_byte_size IS NOT NULL AND chunk.retrieval_text_content_type IS NOT NULL AND EXISTS ( SELECT 1 FROM retrieval_search_document active_doc WHERE active_doc.retrieval_chunk_id = chunk.id AND active_doc.owner_type = #{ownerType} AND active_doc.owner_key = #{ownerKey} AND active_doc.version_id = mv.id AND active_doc.revision_id = mr.id AND active_doc.status = 'ACTIVE' ))) AND (page.page_no IS NULL OR NOT JSON_CONTAINS( COALESCE(mr.excluded_pages_json, JSON_ARRAY()), CAST(page.page_no AS JSON))) AND (
(mv.id = #{source.versionId} AND mr.id = #{source.revisionId})
) ORDER BY FIELD(chunk.id, #{id}), mapping.ordinal LIMIT #{limit}

SELECT chunk.id AS chunk_id, chunk.modality, 1.0 AS score FROM diagram_cell_provenance provenance JOIN diagram ON diagram.id = provenance.diagram_id AND diagram.user_id = #{ownerKey} AND diagram.deleted = 0 JOIN source_citation anchor ON anchor.id = provenance.current_citation_id AND anchor.owner_key = #{ownerKey} AND anchor.target_type = 'DIAGRAM_CELL' JOIN source_citation citation ON citation.diagram_id = provenance.diagram_id AND citation.cell_id = provenance.cell_id AND citation.canvas_version = anchor.canvas_version AND citation.owner_key = #{ownerKey} AND citation.target_type = 'DIAGRAM_CELL' AND citation.state = 'VERIFIED' JOIN citation_evidence cited ON cited.citation_id = citation.id AND cited.use_role = 'SUPPORT' JOIN retrieval_chunk_evidence mapping ON mapping.evidence_id = cited.evidence_id AND mapping.role = 'PRIMARY' JOIN retrieval_chunk chunk ON chunk.id = mapping.retrieval_chunk_id AND chunk.status = 'ACTIVE' AND chunk.citable = TRUE JOIN retrieval_search_document doc ON doc.retrieval_chunk_id = chunk.id AND doc.owner_type = #{ownerType} AND doc.owner_key = #{ownerKey} AND doc.status = 'ACTIVE' WHERE provenance.diagram_id = #{diagramId} AND provenance.canvas_version = #{canvasVersion} AND provenance.support_type = 'EVIDENCE' AND provenance.cell_id IN #{cellId} AND (
(doc.version_id = #{source.versionId} AND doc.revision_id = #{source.revisionId})
) ORDER BY FIELD(provenance.cell_id, #{cellId}), mapping.ordinal LIMIT #{limit}
